export function sky(ctx,w,h,top='#0c2733',bottom='#091319') {const g=ctx.createLinearGradient(0,0,w*.25,h);g.addColorStop(0,top);g.addColorStop(1,bottom);ctx.fillStyle=g;ctx.fillRect(0,0,w,h);}
