from pathlib import Path
from playwright.sync_api import sync_playwright
import base64, json
out=Path('runs/six-studies-s03-portal/portal-browser').resolve()
with sync_playwright() as p:
    browser=p.chromium.launch(headless=True)
    page=browser.new_page(viewport={'width':1440,'height':900})
    page.goto((out/'portal-playback.webm').as_uri())
    page.wait_for_function('document.querySelector(\"video\")?.readyState>=2')
    result=page.evaluate('''async()=>{
      const v=document.querySelector('video');v.pause();
      const canvas=document.createElement('canvas');canvas.width=1440;canvas.height=1000;
      const c=canvas.getContext('2d');c.fillStyle='#10161b';c.fillRect(0,0,1440,1000);
      const times=[1,3,5,8,13,18,22,25,30,34,38,42];
      for(let i=0;i<times.length;i++){
        await new Promise(resolve=>{v.addEventListener('seeked',resolve,{once:true});v.currentTime=times[i];});
        const x=(i%4)*360,y=Math.floor(i/4)*333;
        c.drawImage(v,x,y+24,360,225);c.fillStyle='#d6dfdf';c.font='13px monospace';c.fillText(times[i]+' seconds',x+10,y+17);
      }
      return {data:canvas.toDataURL('image/png').split(',')[1],duration:v.duration,times};
    }''')
    (out/'playback-review.png').write_bytes(base64.b64decode(result.pop('data')))
    (out/'playback-review.json').write_text(json.dumps(result,indent=2)+'\\n',encoding='utf-8')
    print(json.dumps(result))
    browser.close()
